from fractions import Fraction as F
from math import factorial
def bn(n,k):
 r=F(1)
 for i in range(k):r*=F(n-i,i+1)
 return r
def col(g,q,a,b):
 h={-a-g+j:F(factorial(g))*bn(-a,g-j)*bn(a-4,j)*(-1)**j for j in range(g+1)};Q=q+2;s=-1 if b=='-' else 1;o={}
 for e,c in h.items():
  v=e+1+s*Q;o[e]=o.get(e,F())+c*v;o[e+1]=o.get(e+1,F())+c*(v-g)
 o={e:c for e,c in o.items() if c}
 return o if b=='-' else {e+Q:-c for e,c in o.items()}
def sub(v,w,c):
 for e,x in w.items():
  v[e]=v.get(e,F())-c*x
  if not v[e]:del v[e]
